<?php
declare(strict_types=1);namespace App\Command;use App\Imperium\Runtime\Conscription\ModelBoundOperationalManifestationSeatBindingService as S;use Symfony\Component\Console\Attribute\AsCommand;use Symfony\Component\Console\Command\Command;use Symfony\Component\Console\Input\{InputArgument,InputInterface,InputOption};use Symfony\Component\Console\Output\OutputInterface;
#[AsCommand(name:'imperium:conscription:bind-model-bound-operational-manifestation')]final class ConscriptionBindModelBoundOperationalManifestationCommand extends Command{public function __construct(private readonly S$s){parent::__construct();}protected function configure():void{$this->addArgument('assembly-id',InputArgument::REQUIRED)->addOption('json',null,InputOption::VALUE_NONE);}protected function execute(InputInterface$i,OutputInterface$o):int{try{$r=$this->s->bind((string)$i->getArgument('assembly-id'));}catch(\Throwable$e){$o->writeln('<error>REFUSED</error> '.$e->getMessage());return self::FAILURE;}$o->writeln($i->getOption('json')?json_encode($r,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR):'<info>MODEL_BOUND_OPERATIONAL_MANIFESTATION_BOUND</info> '.$r['binding_id']);return self::SUCCESS;}}
